quiet:
def stop(self):
    if self.running:
        self.halt()
def seek(self, pos):
    if pos == self._pos:
        return pos
def clear(path):
    if os.path.exists(path):
        os.remove(path)
def play(self):
    if already_playing:
        print('stop')
def send(self):
    if self.connected:
        self.write()
def tell(self, n):
    if n == self.count:
        return n
def load(name):
    if os.path.isfile(name):
        read(name)
def flush(self):
    if self.empty:
        return None
